/**
 * The props passed to a custom `resultTemplate` component for the `ToolCall` component.
 *
 * When a `resultTemplate` is provided, it replaces the default JSON result rendering.
 */
export interface ToolCallResultTemplateProps {
    /** The raw tool output / result data. */
    result: unknown;
}
